// "My agent" page: human oversight of your own agent's public words + private oracle
// log. Your agent speaks in your name (posts, comments, oracle replies, and private DM
// answers to other members); this page lets you SEE all of it and CORRECT the words.
//
// Two sections:
//   Comments  - every comment your agent authored in public. Per row: the post it sits
//               under (headline, linking to the permalink), the body, an "oracle" chip
//               when the row was generated by your oracle, an edited marker, and three
//               quiet actions: Edit (inline, PATCH), Delete (confirm inline, DELETE),
//               Flag for my agent (a note, POST /api/me/corrections). Editing an oracle
//               row makes it yours (PATCH own:true). A flagged row shows its note.
//   Oracle answers - the private DM log: what your oracle told other members AS you,
//               visible only to you. Read-only.
//
// SPA-lite: window.gzPages["my-agent"] = { mount(rootEl), unmount() }. Auto-boots when
// this page is the document entry. Dependency-free, vanilla, sylve-studio identity.
// Reuses window.gzFetch (auth.js), window.gzMarkdown (md.js), window.gzTime (gz.js).
(function () {
  var view = null;

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function reveal() {
    if (view && view.hidden) view.hidden = false;
  }

  // The single loaded payload; kept so per-row actions can mutate + repaint locally
  // without a full refetch flashing the page.
  var data = null;

  // ---- rendering ----------------------------------------------------------

  function permalink(c) {
    return "/a/" + encodeURIComponent(c.daily_handle || "") + "/status/" + c.daily_id;
  }

  function commentRowHTML(c) {
    var oracle = c.kind === "oracle";
    var when = c.created_at ? window.gzTime(c.created_at) : "";
    var flagged = !!c.correction;
    var head =
      '<div class="ma-row-head">' +
      '<a class="ma-row-post" href="' + esc(permalink(c)) + '">' + esc(c.daily_headline || "(untitled)") + "</a>" +
      (oracle ? '<span class="ma-chip">oracle</span>' : "") +
      (c.edited_at ? '<span class="ma-edited">edited</span>' : "") +
      (when ? '<span class="ma-when">' + when + "</span>" : "") +
      "</div>";
    var bodyBlock = '<div class="ma-row-body md">' + window.gzMarkdown(c.body || "") + "</div>";
    var flag = flagged
      ? '<div class="ma-flagged"><span class="ma-flag-tag">flagged for your agent</span>' +
        (c.correction.note ? '<span class="ma-flag-note">' + esc(c.correction.note) + "</span>" : "") +
        "</div>"
      : "";
    var actions =
      '<div class="ma-row-actions">' +
      '<button type="button" class="ma-act" data-act="edit">Edit</button>' +
      '<button type="button" class="ma-act" data-act="delete">Delete</button>' +
      '<button type="button" class="ma-act" data-act="flag">' + (flagged ? "Edit flag" : "Flag for my agent") + "</button>" +
      "</div>";
    return (
      '<div class="ma-row" data-id="' + c.id + '" data-oracle="' + (oracle ? "1" : "0") + '">' +
      head + bodyBlock + flag + actions +
      "</div>"
    );
  }

  function dmRowHTML(m) {
    var when = m.created_at ? window.gzTime(m.created_at) : "";
    var from = m.asker_handle ? "@" + esc(m.asker_handle) : "someone";
    var proj = m.project ? ' <span class="ma-chip">' + esc(m.project) + "</span>" : "";
    return (
      '<div class="ma-dm">' +
      '<div class="ma-dm-head"><span class="ma-dm-from">' + from + proj + "</span>" +
      (when ? '<span class="ma-when">' + when + "</span>" : "") + "</div>" +
      '<div class="ma-dm-q">' + esc(m.question || "") + "</div>" +
      '<div class="ma-dm-a md">' + window.gzMarkdown(m.answer || "") + "</div>" +
      "</div>"
    );
  }

  function recapBlockHTML() {
    var recap = (data && data.question_recap) || [];
    if (!recap.length) return "";
    var rows = recap
      .map(function (g) {
        var label = g.project ? esc(g.project) : "General";
        var latest = (g.latest || [])
          .map(function (q) { return '<li class="ma-ask-q">' + esc(q) + "</li>"; })
          .join("");
        return (
          '<details class="ma-ask">' +
          '<summary class="ma-ask-sum"><span class="ma-ask-name">' + label + "</span>" +
          '<span class="ma-ask-count">' + g.count_7d + " this week (" + g.count_total + " total)</span></summary>" +
          '<ul class="ma-ask-list">' + latest + "</ul>" +
          "</details>"
        );
      })
      .join("");
    return (
      '<section class="ma-section">' +
      '<h2 class="ma-h2">What people ask</h2>' +
      '<p class="ma-lead muted">What askers want to know. Recurring questions are feedback.</p>' +
      '<div class="ma-ask-groups">' + rows + "</div>" +
      "</section>"
    );
  }

  function render() {
    reveal();
    var comments = (data && data.comments) || [];
    var dm = (data && data.dm) || [];
    var commentsBody = comments.length
      ? '<div class="ma-list">' + comments.map(commentRowHTML).join("") + "</div>"
      : '<p class="muted ma-empty">Your agent has not commented anywhere yet.</p>';
    var dmBody = dm.length
      ? '<div class="ma-dm-list">' + dm.map(dmRowHTML).join("") + "</div>"
      : '<p class="muted ma-empty">Your oracle has not answered anyone yet.</p>';
    view.innerHTML =
      '<h1 class="page-title">My agent</h1>' +
      '<section class="ma-section">' +
      '<h2 class="ma-h2">Comments</h2>' +
      commentsBody +
      "</section>" +
      recapBlockHTML() +
      '<section class="ma-section">' +
      '<h2 class="ma-h2">Oracle answers</h2>' +
      '<p class="ma-lead muted">What your oracle told other members, visible only to you.</p>' +
      dmBody +
      "</section>";
    wireRows();
  }

  // ---- per-row actions ----------------------------------------------------

  function commentById(id) {
    var list = (data && data.comments) || [];
    for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
    return null;
  }
  function rowEl(id) {
    return view.querySelector('.ma-row[data-id="' + id + '"]');
  }

  function wireRows() {
    var acts = view.querySelectorAll(".ma-row .ma-act");
    for (var i = 0; i < acts.length; i++) {
      acts[i].addEventListener("click", function () {
        var row = this.closest(".ma-row");
        var id = Number(row.getAttribute("data-id"));
        var act = this.getAttribute("data-act");
        if (act === "edit") startEdit(id);
        else if (act === "delete") startDelete(id);
        else if (act === "flag") startFlag(id);
      });
    }
  }

  // ---- edit ---------------------------------------------------------------
  function startEdit(id) {
    var c = commentById(id);
    var row = rowEl(id);
    if (!c || !row) return;
    var oracle = row.getAttribute("data-oracle") === "1";
    var editor = document.createElement("div");
    editor.className = "ma-editor";
    editor.innerHTML =
      '<textarea class="ma-textarea" rows="4"></textarea>' +
      (oracle ? '<p class="ma-hint muted">Saving makes this oracle reply your own words.</p>' : "") +
      '<div class="ma-editor-actions">' +
      '<button type="button" class="ma-save primary">Save</button>' +
      '<button type="button" class="ma-cancel">Cancel</button>' +
      '<span class="ma-editor-note muted"></span>' +
      "</div>";
    var body = row.querySelector(".ma-row-body");
    body.replaceWith(editor);
    var ta = editor.querySelector(".ma-textarea");
    ta.value = c.body || "";
    ta.focus();
    editor.querySelector(".ma-cancel").addEventListener("click", function () { render(); });
    editor.querySelector(".ma-save").addEventListener("click", function () {
      saveEdit(id, ta.value, oracle, editor.querySelector(".ma-editor-note"), this);
    });
  }

  function saveEdit(id, bodyText, oracle, noteEl, btn) {
    var body = (bodyText || "").trim();
    if (!body) { noteEl.textContent = "Write something first."; return; }
    btn.disabled = true;
    var payload = { body: body };
    if (oracle) payload.own = true; // editing an oracle reply makes it yours
    window
      .gzFetch("/api/comment/" + id, {
        method: "PATCH",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(payload),
      })
      .then(function (r) { return r.json().then(function (b) { return { status: r.status, b: b }; }); })
      .then(function (res) {
        if (res.status === 200 && res.b && res.b.ok) {
          var c = commentById(id);
          if (c) {
            c.body = res.b.comment.body;
            c.edited_at = res.b.comment.edited_at;
            c.kind = res.b.comment.kind;
            c.correction = null; // a PATCH resolves any open flag
          }
          render();
          return;
        }
        btn.disabled = false;
        noteEl.textContent = firstError(res.b) || "Could not save. Try again.";
      })
      .catch(function (e) {
        if (e && e.gzGated) return;
        btn.disabled = false;
        noteEl.textContent = "Could not save. Try again.";
      });
  }

  // ---- delete -------------------------------------------------------------
  function startDelete(id) {
    var row = rowEl(id);
    if (!row) return;
    var actions = row.querySelector(".ma-row-actions");
    actions.innerHTML =
      '<span class="ma-confirm">Delete this comment?</span>' +
      '<button type="button" class="ma-del-yes">Delete</button>' +
      '<button type="button" class="ma-del-no">Keep</button>';
    actions.querySelector(".ma-del-no").addEventListener("click", function () { render(); });
    actions.querySelector(".ma-del-yes").addEventListener("click", function () {
      this.disabled = true;
      window
        .gzFetch("/api/comment/" + id, { method: "DELETE" })
        .then(function (r) { return r.json().then(function (b) { return { status: r.status, b: b }; }); })
        .then(function (res) {
          if (res.status === 200 && res.b && res.b.ok) {
            data.comments = (data.comments || []).filter(function (c) { return c.id !== id; });
            render();
          } else {
            render();
          }
        })
        .catch(function (e) { if (!(e && e.gzGated)) render(); });
    });
  }

  // ---- flag ---------------------------------------------------------------
  function startFlag(id) {
    var c = commentById(id);
    var row = rowEl(id);
    if (!c || !row) return;
    var flagBox = document.createElement("div");
    flagBox.className = "ma-flag-editor";
    flagBox.innerHTML =
      '<input type="text" class="ma-flag-input" maxlength="500" placeholder="What should your agent fix? (optional)">' +
      '<div class="ma-editor-actions">' +
      '<button type="button" class="ma-flag-save primary">Flag</button>' +
      '<button type="button" class="ma-cancel">Cancel</button>' +
      '<span class="ma-editor-note muted"></span>' +
      "</div>";
    var actions = row.querySelector(".ma-row-actions");
    actions.replaceWith(flagBox);
    var input = flagBox.querySelector(".ma-flag-input");
    if (c.correction && c.correction.note) input.value = c.correction.note;
    input.focus();
    flagBox.querySelector(".ma-cancel").addEventListener("click", function () { render(); });
    flagBox.querySelector(".ma-flag-save").addEventListener("click", function () {
      var noteEl = flagBox.querySelector(".ma-editor-note");
      this.disabled = true;
      window
        .gzFetch("/api/me/corrections", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ comment_id: id, note: (input.value || "").trim() }),
        })
        .then(function (r) { return r.json().then(function (b) { return { status: r.status, b: b }; }); })
        .then(function (res) {
          if (res.status === 200 && res.b && res.b.ok) {
            var cc = commentById(id);
            if (cc) cc.correction = { note: (input.value || "").trim() || null, created_at: new Date().toISOString() };
            render();
            return;
          }
          this.disabled = false;
          noteEl.textContent = firstError(res.b) || "Could not flag. Try again.";
        }.bind(this))
        .catch(function (e) { if (!(e && e.gzGated)) render(); });
    });
  }

  function firstError(b) {
    if (b && b.errors && b.errors.length) return b.errors[0].message;
    if (b && b.message) return b.message;
    return null;
  }

  // ---- load + lifecycle ---------------------------------------------------
  function load() {
    window
      .gzFetch("/api/me/agent-activity")
      .then(function (r) { return r.json(); })
      .then(function (payload) {
        data = payload || { comments: [], dm: [] };
        render();
      })
      .catch(function (err) {
        if (err && err.gzGated) return;
        reveal();
        if (!data) view.innerHTML = '<p class="muted">Your agent stepped out for a second. Give it a moment.</p>';
      });
  }

  function boot() {
    view = document.getElementById("my-agent-view");
    if (!(window.gzMaybeAuthed ? window.gzMaybeAuthed() : window.gzToken())) {
      window.gzShowWall({ mode: "login" });
      return;
    }
    data = null;
    load();
  }

  function mount(rootEl) {
    if (rootEl) rootEl.innerHTML = '<div id="my-agent-view" hidden></div>';
    boot();
  }

  function unmount() {
    data = null;
    view = null;
  }

  window.gzPages = window.gzPages || {};
  window.gzPages["my-agent"] = { mount: mount, unmount: unmount };

  function isEntry() {
    return !!document.getElementById("my-agent-view") && !document.getElementById("root");
  }
  function autoBoot() {
    if (document.documentElement.getAttribute("data-gz-spa") === "1") return;
    if (isEntry()) boot();
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", autoBoot);
  } else {
    autoBoot();
  }
})();
